"""Render a self-contained showcase from executed evidence, without external assets."""
import csv
import html
import json
from pathlib import Path

def build(evidence,output):
    report=json.loads((evidence/'validation.json').read_text())
    cases=json.loads((evidence/'scenarios/scenarios.json').read_text())['cases']
    esc=lambda value: html.escape(str(value))
    cards=''
    for i,c in enumerate(cases,1):
        status=c['symptom']['status']
        symptom='Connection failure' if status is None else f'HTTP {status}'
        cards+=f'<article><span class="eyebrow">CASE {i:02d} · VERIFIED</span><h3>{esc(c["scenario"].replace("_"," ").title())}</h3><p class="flow">{symptom} → HTTP {c["after_fix"]["status"]}</p><p>{esc(c["diagnosis"])}</p><details><summary>Inspect captured evidence</summary><pre>{esc(json.dumps(c,indent=2))}</pre></details></article>'
    rows=''
    for state in ('healthy','unhealthy'):
        data=list(csv.DictReader((evidence/state/'health.csv').open()))
        for r in data:
            rows+='<tr>'+''.join(f'<td>{esc(x)}</td>' for x in (state,r['recorded_at'],r['cpu_pct'],r['memory_pct'],r['disk_pct'],r['http_status'] or 'unreachable'))+'</tr>'
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Linux Operations Lab | Sibly Noman</title><style>
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f1f5f8;color:#183045;font:16px/1.6 system-ui,sans-serif}header{background:#102d3d;color:white;padding:70px max(6vw,24px)}main{max-width:1150px;margin:auto;padding:38px 24px}h1{font-size:clamp(35px,6vw,64px);line-height:1.1;margin:16px 0}h2{font-size:28px;margin-top:48px}h3{font-size:21px}.eyebrow{letter-spacing:2px;font-size:12px;font-weight:700;color:#25bba5}header p{max-width:730px;color:#c6d9e2}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}article,.note{background:white;border:1px solid #dbe4ea;border-radius:12px;padding:26px}.stats{display:flex;flex-wrap:wrap;gap:32px;margin-top:30px}.stats strong{display:block;font-size:32px;color:#54e0c4}.stats span{font-size:13px;color:#c6d9e2}.flow{font-weight:700;color:#087d70}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef3f7;padding:16px;font-size:12px}summary{cursor:pointer;font-weight:600}table{border-collapse:collapse;width:100%;background:white;font-size:13px}td,th{text-align:left;padding:12px;border-bottom:1px solid #e2e8ef}.scroll{overflow:auto}a{color:#087d70}footer{padding:30px 0;color:#586e80;font-size:13px}@media(max-width:650px){.grid{grid-template-columns:1fr}header{padding:42px 24px}}</style></head><body>
<header><span class="eyebrow">SIBLY NOMAN / SYSTEMS PORTFOLIO</span><h1>Linux Operations Lab</h1><p>From an unavailable endpoint to a verified recovery. Controlled TCP and HTTP failures, observable Linux metrics, and repeatable Python checks.</p><div class="stats"><div><strong>4 / 4</strong><span>Recovery scenarios passed</span></div><div><strong>4 / 4</strong><span>Metric tests passed</span></div><div><strong>10</strong><span>Health samples checked</span></div></div></header>
<main><div class="note"><b>Evidence, with context.</b> This is a local lab, not a production incident report. The bundled run was executed in the assistant environment. Physical hardware work, multi-host networking and personal laptop execution are not claimed.</div><h2>Investigate the right layer</h2><div class="grid">'''+cards+'''</div><h2>Host monitoring, with SQL evidence</h2><p>Python reads Linux CPU, memory and filesystem metrics, probes the service, and stores samples in SQLite. Five unreachable-service samples and five healthy-service samples were verified. Resource values reflect the execution environment, not dedicated physical hardware.</p><div class="scroll"><table><thead><tr><th>Test</th><th>UTC timestamp</th><th>CPU %</th><th>Memory %</th><th>Disk %</th><th>HTTP</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><h2>Reproduce the complete demonstration</h2><pre>python3 scripts/complete_demo.py</pre><p>One command runs unit tests, starts and stops the isolated service, checks failure and recovery, verifies SQLite output and regenerates this page. No pip dependencies or database server required. Linux and Python 3.10+ are required.</p><h2>Engineering choices</h2><div class="grid"><article><h3>Diagnose before restarting</h3><p>A refused connection, HTTP 404 and HTTP 503 describe different failure layers. Each case records the symptom, targeted fix and successful HTTP check.</p></article><article><h3>Unknown stays unknown</h3><p>A missing service response does not become a healthy reading. CPU intervals with no elapsed ticks remain unknown. Metrics and application health are evaluated separately.</p></article></div><footer>Executed: '''+esc(report['generated_at'])+' · Python '+esc(report['python'])+''' · Automated local evidence.<br>Source package includes code, runbooks, tests, evidence and MIT license. This page is static; it does not connect to your laptop.</footer></main></body></html>'''
    output.parent.mkdir(parents=True,exist_ok=True);output.write_text(page)
